package tn.smartuniversity.security;
import io.jsonwebtoken.Jwts; import io.jsonwebtoken.security.Keys; import java.nio.charset.StandardCharsets; import java.util.Date; import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import tn.smartuniversity.user.AppUser;
@Service public class JwtService { @Value("${app.jwt.secret}") private String secret; @Value("${app.jwt.expiration-ms}") private long expiration; private SecretKey key(){return Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));} public String generate(AppUser u){return Jwts.builder().subject(u.getEmail()).claim("role",u.getRole()).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+expiration)).signWith(key()).compact();} public String subject(String token){return Jwts.parser().verifyWith(key()).build().parseSignedClaims(token).getPayload().getSubject();} }
